#pragma once

#include <span>
#include <string_view>

namespace rummage::i18n::detail {

// A translation as compiled in: its language code (the file name of data/i18n/<code>.toml)
// and the file's TOML text, parsed on first use.
struct Catalog {
    std::string_view code;
    std::string_view toml;
};

// Every data/i18n/*.toml, sorted by code (generated by src/core/CMakeLists.txt).
std::span<const Catalog> catalogs();

}  // namespace rummage::i18n::detail
